async prepareChatBindings(chatId: number, chatMessages: AiChatMessage[])
    : Promise<SeedBindingInfo[]> {
  let context = this.getChatAgentContext(chatId);
  let dirty = false;

  if (context.alwaysAvailableCapsuleIds === undefined) {
    // Freeze the ambient set + order on first use. Ordered by gatekeeper id (immutable) for
    // determinism. New singletons the owner gains only appear in chats started afterwards; a
    // since-disconnected one stays in the frozen list but becomes inert.
    context.alwaysAvailableCapsuleIds = [...this.storage.gatekeepers.list()]
        .filter(gk => gk.creationSpec?.type === "ambient")
        .map(gk => gk.id)
        .toSorted((a, b) => a - b);
    dirty = true;
  }
  let ambientIds = context.alwaysAvailableCapsuleIds;

  if (context.bindings === undefined) {
    let seed: Record<string, WorkpieceId> = Object.create(null);
    if (context.spawnerConfig) {
      // Spawned chats see only the spawner's configured bindings. The frozen config may
      // predate the structured env -- `env?: string[]` was a binding-name allowlist, with
      // absence meaning "unrestricted" -- in which case it is resolved against the current
      // default binding list, mirroring how the storage migration rewrites stored spawner
      // records.
      let env = context.spawnerConfig.env as
          Record<string, WorkpieceId> | string[] | undefined;
      if (env === undefined || Array.isArray(env)) {
        for (let [name, target] of Object.entries(this.defaultBindingList())) {
          if (env === undefined || env.includes(name)) seed[name] = target;
        }
      } else {
        // Drop entries whose targets no longer exist.
        for (let [name, target] of Object.entries(env)) {
          if (this.storage.gadgets.get(target) || this.storage.gatekeepers.get(target)) {
            seed[name] = target;
          }
        }
      }
    } else {
      Object.assign(seed, this.defaultBindingList());
    }

    // Fold the ambient resources into the seed, each named by its gatekeeper's suggested
    // binding name (deduped); skip any whose target already has a name in the seed.
    let seededTargets = new Set(Object.values(seed));
    for (let id of ambientIds) {
      if (seededTargets.has(id)) continue;
      let gk = this.storage.gatekeepers.get(id);
      if (!gk) continue;  // disconnected since the freeze -- inert, no name needed
      let suggested: string | undefined;
      try {
        suggested = (await this.getGatekeeperFacet(id).describe()).suggestedBindingName;
      } catch (err) {
        this.logger.warn("failed to fetch suggested binding name for ambient resource", {
          event: "chat.binding.ambient.describe.failed", gatekeeperId: id, error: err,
        });
      }
      seed[fallbackBindingName(suggested || "RESOURCE", name => name in seed)] = id;
    }

    context.bindings = seed;
    dirty = true;
  }
  let seedMap = context.bindings;

  // --- The naming chokepoint: stamp binding names onto persisted messages that lack them. ---
  // First collect every name already in the chat's scope (and a target -> name map for reuse)
  // from the seed plus the log -- including the callback PARAMS_<n> names the replay loop will
  // allocate, simulated the same way, so a minted name can't collide with anything replay will
  // bind -- then name and stamp the unnamed, in log order. We scan and stamp the caller's
  // in-memory message objects (not a fresh storage listing, which would deserialize separate
  // copies): the caller replays these same objects right after we return, and must see the
  // names we stamp. (This scan can't reuse chatScopeNames: that method rereads the chat context
  // from storage, where a seed map created just above isn't persisted yet.)
  // TODO: The logic here is replaying the chat message log to regenerate the binding map.
  //   Could this logic be incorporated into the chat log replay that happens inside runAgent(),
  //   in agent.ts? It feels similar, and it would be nice to consolidate all "tool call replay"
  //   logic into one place. Ideally, there shouldn't be logic outside of agent.ts that is
  //   interpreting tool semantics at all (though making that true will require more refactoring
  //   than just this).
  let taken = new Set(Object.keys(seedMap));
  let nameByTarget = new Map<WorkpieceId, string>();
  for (let [name, target] of Object.entries(seedMap)) {
    if (!nameByTarget.has(target)) nameByTarget.set(target, name);
  }
  // Names allocated before the compaction boundary aren't in `chatMessages`, so take them from the
  // checkpoint. Skipping them would hand a new resource a name the prefix already bound, and replay
  // -- which seeds its map from the same checkpoint -- would keep resolving that name to the older
  // target while rendering the new resource's link with it.
  for (let [name, entry] of this.getActiveChatCompaction(chatId)?.chatBindings ?? []) {
    taken.add(name);
    if (entry.type === "workpiece" && !nameByTarget.has(entry.id)) {
      nameByTarget.set(entry.id, name);
    }
  }
  let namingLog = chatMessages;
  let anythingToName = false;
  let callbackNameCounter = 0;
  for (let msg of namingLog) {
    if (msg.type === "message") {
      for (let capsule of msg.capsules ?? []) {
        if (capsule.bindingName !== undefined) {
          taken.add(capsule.bindingName);
          if (!nameByTarget.has(capsule.gatekeeperId)) {
            nameByTarget.set(capsule.gatekeeperId, capsule.bindingName);
          }
        } else {
          anythingToName = true;
        }
      }
      for (let call of msg.toolCalls ?? []) {
        if (call.toolName === "createGadget") {
          taken.add(call.input.bindingName);
          if (call.output && !nameByTarget.has(call.output.gadgetId)) {
            nameByTarget.set(call.output.gadgetId, call.input.bindingName);
          }
        }
      }
    } else if (msg.type === "connectionRequest") {
      if (msg.bindingName !== undefined) {
        if (msg.state !== "denied") taken.add(msg.bindingName);
        if (msg.gatekeeperId !== undefined && !nameByTarget.has(msg.gatekeeperId)) {
          nameByTarget.set(msg.gatekeeperId, msg.bindingName);
        }
      } else if (msg.state !== "denied") {
        anythingToName = true;
      }
    } else if (msg.type === "changes") {
      for (let created of msg.createdGadgets ?? []) {
        taken.add(created.bindingName);
        if (!nameByTarget.has(created.gadgetId)) {
          nameByTarget.set(created.gadgetId, created.bindingName);
        }
      }
    } else if (msg.type === "agentCallback") {
      // Claim the PARAMS_<n> name the replay loop will allocate for this callback (kept in
      // sync with runAgent in agent.ts and with chatScopeNames).
      let name: string;
      do {
        name = `PARAMS_${++callbackNameCounter}`;
      } while (taken.has(name));
      taken.add(name);
    }
  }

  if (anythingToName) {
    let quick = await this.#getNamingQuickModel();

    // Name one resource: reuse the target's existing name in scope when there is one, else ask
    // the quick model, else fall back to the gatekeeper's suggested binding name (suffixed to
    // uniqueness). Never fails -- worst case the generic fallback names it RESOURCE_<n>.
    let nameFor = async (target: WorkpieceId | undefined, subject: string)
        : Promise<string> => {
      if (target !== undefined) {
        let existing = nameByTarget.get(target);
        if (existing !== undefined) return existing;
      }
      let name = quick ? await this.generateBindingName(subject, taken, quick) : undefined;
      if (name === undefined) {
        let suggested: string | undefined;
        if (target !== undefined && this.storage.gatekeepers.get(target)) {
          try {
            suggested =
                (await this.getGatekeeperFacet(target).describe()).suggestedBindingName;
          } catch {
            // Fall through to the generic fallback.
          }
        }
        name = fallbackBindingName(suggested || "RESOURCE", n => taken.has(n));
      }
      taken.add(name);
      if (target !== undefined) nameByTarget.set(target, name);
      return name;
    };

    for (let msg of namingLog) {
      let stamped = false;
      if (msg.type === "message") {
        for (let capsule of msg.capsules ?? []) {
          if (capsule.bindingName !== undefined) continue;
          capsule.bindingName =
              await nameFor(capsule.gatekeeperId, capsule.description.title);
          stamped = true;
        }
      } else if (msg.type === "connectionRequest" &&
                 msg.bindingName === undefined && msg.state !== "denied") {
        msg.bindingName = await nameFor(
            msg.gatekeeperId, `${msg.resourceTitle} (${msg.vendorName})`);
        stamped = true;
      }
      if (stamped) {
        // Guard against the chat having been deleted during the awaits above (deleteChat is
        // the single cleanup point; a put here would resurrect a deleted message). Bump the
        // timestamp so offline clients re-receive the mutated message (same pattern as
        // connection accept/deny stamping).
        if (!this.storage.chatMeta.get(chatId)) break;
        msg.timestamp = this.getChatTimestamp();
        this.storage.chats.put(msg);
      }
    }
  }

  // Complete/refresh the cached discovery catalogs for the frozen ambient set.
  let {snapshots, changed} = await completeAgentCatalogSnapshot(
      context.alwaysAvailableCatalogs,
      ambientIds,
      async gatekeeperId => {
        let record = this.storage.gatekeepers.get(gatekeeperId);
        if (!record) return null;  // disconnected since the chat froze its set — no catalog.
        try {
          using authorizer = new RpcStub<ObservationAuthorizer>(new ApprovalQueueImpl(
              this, gatekeeperId, {from: "agent", chatId}));
          // The catalog comes from the installed gatekeeper facet (gadget-side), authorized as an
          // observation via the approval queue. getAgentCatalog is optional on Gatekeeper; ambient
          // resources always implement it (the agent relies on it for discovery), so we view the
          // facet through CatalogGatekeeperFacet (derived from the contract) to call it directly.
          // The DurableObjectStub proxy unstubifies the RpcStub param to its target type; the
          // native stub forwards transparently at runtime.
          let facet = this.getGatekeeperFacet(gatekeeperId) as unknown as CatalogGatekeeperFacet;
          let catalog = await facet.getAgentCatalog(
              authorizer as unknown as ObservationAuthorizer);
          return catalog ? normalizeAgentCatalog(catalog) : null;
        } catch (error) {
          reportIssue("overseer.catalog-fallback", error, {
            handled: true,
            attributes: {
              ...obsContext.get(), gadgetId: this.ctx.id.toString(), gatekeeperId,
            },
          });
          this.logger.warn("failed to load agent catalog", {
            event: "agent.catalog.load.failed",
            gatekeeperId, resourceTitle: record.resourceTitle, error,
          });
          return null;
        }
      });
  if (changed) {
    context.alwaysAvailableCatalogs = snapshots;
    dirty = true;
  }
  if (dirty) {
    // The work above is async, so the chat could have been deleted meanwhile. Don't resurrect
    // its per-chat storage: deleteChat is the single cleanup point (see its comment) and
    // removes chatMeta, so a missing chatMeta means the chat is gone.
    if (this.storage.chatMeta.get(chatId)) {
      this.storage.chatContext.put(context);
    }
  }

  // Materialize the seed entries, skipping targets that no longer exist (mirroring env build);
  // ambient entries carry their catalogs.
  let catalogs = new Map(snapshots.map(entry => [entry.gatekeeperId, entry.catalog]));
  let ambientSet = new Set(ambientIds);
  let result: SeedBindingInfo[] = [];
  for (let [name, target] of Object.entries(seedMap)) {
    let gadget = this.storage.gadgets.get(target);
    if (gadget) {
      result.push({name, target, title: gadget.title, isGadget: true});
      continue;
    }
    let gk = this.storage.gatekeepers.get(target);
    if (!gk) continue;
    let info: SeedBindingInfo =
        {name, target, title: gk.resourceTitle || "(untitled resource)", isGadget: false};
    if (ambientSet.has(target)) info.catalog = catalogs.get(target) ?? null;
    result.push(info);
  }
  return result;

export function buildCompactionState(
    messages: AiChatMessage[], compactedTo: number,
    initialBindings: [string, ChatBindingEntry][],
    previous: CompactionCheckpoint | undefined)
    : Omit<CompactionCheckpoint, "chatId" | "compactedTo" | "summary"> {
  let compacted = messages.filter(message => message.sequence < compactedTo);
  let chatBindings = new Map(previous?.chatBindings ?? initialBindings);
  let callbackNameCounter = 0;
  let nextChangeId = previous?.nextChangeId ?? 0;

  for (let message of compacted) {
    if (message.type === "message") {
      for (let capsule of message.capsules ?? []) {
        if (capsule.bindingName !== undefined && !chatBindings.has(capsule.bindingName)) {
          chatBindings.set(capsule.bindingName, {type: "workpiece", id: capsule.gatekeeperId});
        }
      }
      for (let call of message.toolCalls ?? []) {
        if (call.error) continue;
        if (call.toolName === "createGadget" && call.output !== undefined) {
          chatBindings.set(call.input.bindingName, {type: "workpiece", id: call.output.gadgetId});
        }
      }
    } else if (message.type === "agentCallback") {
      let name: string;
      do {
        name = `PARAMS_${++callbackNameCounter}`;
      } while (chatBindings.has(name));
      chatBindings.set(name, {type: "value", messageSequence: message.sequence});
    } else if (message.type === "connectionRequest" && message.state === "accepted" &&
               message.gatekeeperId !== undefined && message.bindingName !== undefined) {
      if (!chatBindings.has(message.bindingName)) {
        chatBindings.set(message.bindingName, {type: "workpiece", id: message.gatekeeperId});
      }
    } else if (message.type === "changes") {
      for (let {gadgetId, bindingName} of message.createdGadgets ?? []) {
        if (!chatBindings.has(bindingName)) {
          chatBindings.set(bindingName, {type: "workpiece", id: gadgetId});
        }
      }
      ++nextChangeId;
    }
  }

  // Pins active at the boundary, and the epoch it lies in: seeded from the previous checkpoint
  // and folded over the compacted span -- an epoch boundary (an epochBoundary merge, or a
  // migrated chat's conversionBoundary changes message) resets both, and a surviving "changes"
  // message's declarations accumulate. Statuses are computed over the compacted span alone,
  // which is sound because rollbackChatCompaction guarantees no revert in the tail reaches
  // below the boundary.
  let statuses = chatChangeStatuses(compacted);
  let pins = new Map((previous?.pins ?? []).map(pin => [pin.gadgetId, pin] as const));
  let epoch = previous?.epoch;
  for (let message of compacted) {
    if (message.type === "merge" && message.epochBoundary) {
      pins.clear();
      epoch = message.sequence;
    } else if (message.type === "changes" && statuses.get(message.sequence) !== "reverted") {
      if (message.conversionBoundary) {
        pins.clear();
        epoch = message.sequence;
      }
      for (let pin of message.pins ?? []) pins.set(pin.gadgetId, pin);
    }
  }

  // Proposed changes stay addressable by sequence until a merge accepts them or a revert drops
  // them; the checkpoint carries their composition so replay needn't load the compacted
  // messages. A carried-forward prefix is addressed below every message in this span: the
  // previous checkpoint already folded it, so nothing here can accept or revert part of it.
  // Composition is bounded by content size, not edit count, so `proposedChange` can't grow with
  // history the way merged CRDT updates could.
  let proposed = foldProposedChanges(
      compacted,
      previous?.proposedChange !== undefined
          ? [{sequence: -1, change: previous.proposedChange}] : []);
  let proposedChange: CodeChange | undefined;
  for (let batch of proposed) {
    if (batch.change === undefined) continue;
    proposedChange = proposedChange === undefined
        ? batch.change : composeCodeChange(proposedChange, batch.change);
  }

  return {
    chatBindings: [...chatBindings],
    nextChangeId,
    pins: pins.size === 0 ? undefined : [...pins.values()],
    epoch,
    proposedChange,
  };

/** CSP ignores `sandbox` in a meta tag, so serve the document through interception with a header. */
const EXPORT_DOCUMENT_URL = "https://gadget-export.invalid/";
// TODO: CSP and request interception do not cover WebRTC/STUN. The same gap exists for Gadgets
// running inside an iframe in the user's browser. We should close the gap in both places. For now,
// extending the same gap to remotely-rendered gadgets is acceptable.
const EXPORT_DOCUMENT_CSP = "default-src 'none'; frame-src 'none'; script-src data:; " +
  "style-src data: 'unsafe-inline'; img-src data: blob:; media-src data: blob:; " +
  "font-src data:; object-src 'none'; base-uri 'none'; form-action 'none'; " +
  "connect-src 'none'; sandbox allow-scripts;";
const STATIC_HTML_CSP = "default-src 'none'; frame-src 'none'; script-src 'none'; " +
  "style-src data: 'unsafe-inline'; img-src data:; media-src data:; font-src data:; " +
  "object-src 'none'; base-uri 'none'; form-action 'none'; connect-src 'none';";
const DEFAULT_EXPORT_FORMATS: GadgetExportFormat[] = [
  {
    id: "html",
    label: "HTML",
    mode: "browser",
    contentType: "text/html",
    fileExtension: ".html",
  },
  {
    id: "pdf",
    label: "PDF",
    mode: "browser",
    contentType: "application/pdf",
    fileExtension: ".pdf",
  },
];

/** Returns fresh copies of the default HTML and PDF export formats. */
export function defaultExportFormats(): GadgetExportFormat[] {
  return DEFAULT_EXPORT_FORMATS.map(format => ({...format}));
}

/** Validates and normalizes export format metadata returned by Gadget code. */
export function validateExportFormats(value: unknown): GadgetExportFormat[] {
  const result = EXPORT_FORMATS_SCHEMA.safeParse(value);
  if (!result.success) {
    throw new Error(result.error.issues[0]?.message ?? "Invalid Gadget export formats.");
  }
  return result.data;
}

export function legacyChatBaseVersion(
    checkpoint: CompactionCheckpoint | undefined,
    messages: Iterable<AiChatMessage>): number | "current" {
  let anchor = checkpoint?.observedCodeVersion;
  let bump = (version: number | undefined) => {
    if (version !== undefined && (anchor === undefined || version > anchor)) anchor = version;
  };
  for (let msg of messages) {
    if (msg.type === "message") {
      for (let call of msg.toolCalls ?? []) bump(call.observedCodeVersion);
    } else if (msg.type === "changes") {
      bump(msg.observedCodeVersion);
    } else if (msg.type === "merge") {
      bump(msg.version);
    }
  }
  return anchor ?? "current";
}
  async #migrateToGitStorage(): Promise<void> {
    let startedAt = Date.now();
    let { commits } = await migrateCodeLogToGit({
      storage: this.storage,
      gitStore: this.gitStore,
      ownerIdentity: await this.#ownerCommitIdentity(),

  async putConnectedAccount(record: ConnectedAccountRecord) {
    let uniqueName = record.description.uniqueName;
    if (uniqueName &&
        this.#findConnectedAccountByIdentity(record.vendorId, uniqueName, record.id)) {
      // OAuth providers often return the currently logged-in identity when the user tries to add
      // another account. Avoid showing duplicate account rows: keep the existing record stable for
      // any UI references, and revoke the newly-created duplicate grant.
      await record.account.revoke();
      return;
    }

    this.storage.connectedAccounts.put(record);
  }

  async markCredentialsExpired(accountId: number) {
    let record = this.storage.connectedAccounts.get(accountId);
    if (!record) throw new Error("No such account.");

    if (!record.credentialsExpired) {
      record.credentialsExpired = true;
      this.storage.connectedAccounts.put(record);
    }
  }

  async markCredentialsRestored(accountId: number, expiresAt?: Date) {
    let record = this.storage.connectedAccounts.get(accountId);
    if (!record) throw new Error("No such account.");

    // Re-fetch description since the user may have re-authed with different info.
    record.description = await record.account.describe();
    record.credentialsExpired = false;
    record.credentialExpiresAt = expiresAt;
    this.storage.connectedAccounts.put(record);
export interface GatekeeperConnectCallback extends WorkerEntrypoint {
  /**
   * Indicates the connection completed successfully.
   *
   * `expiresAt`, if provided, indicates when the credentials are expected to stop being
   * refreshable. Do not pass the expiry of a short-lived access token if the gatekeeper can
   * refresh it transparently; that token-cache expiry is internal to the gatekeeper. This allows
   * the Workshop to proactively show the account as expired in the UI without waiting for an
   * operation to fail. If not provided, the system relies on the gatekeeper calling
   * `credentialsExpired()` when a refresh or authorization failure is detected.
   */
  complete(user: Fetcher<GatekeeperUser>, expiresAt?: Date): Promise<void>;

  // Note: If the authorization flow fails, the error can be displayed directly to the user, and
  // the callback can be discarded.

  /**
   * Called when the gatekeeper discovers that credentials have expired or been revoked (e.g., a
   * token refresh fails with an authorization error). The Workshop records this and notifies
   * subscribers so the UI can reflect the expired state.
   *
   * The gatekeeper should avoid calling this repeatedly -- once is sufficient. Subsequent calls
   * are harmless but redundant.
   */
  credentialsExpired(): Promise<void>;

  /**
   * Called when credentials have been restored (e.g., after a reconnect flow completes).
   * `expiresAt` is the new expected refreshability expiration date, if known.
   */
  credentialsRestored(expiresAt?: Date): Promise<void>;
}

  async authorizeObservation(gatekeeperId: number, description: ObservationDescription,
                             caller: GatekeeperCaller): Promise<void> {
    if (description.prohibitAllSharing) {
      if ((await this.getSharingManager()).hasAnyShares()) {
        throw new Error(
            "This observation was blocked because it contains sensitive data that must only be " +
            "shown to the account owner, but this workspace is shared with other users. Try again " +
            "from a workspace that is not shared.");
      }

      this.storage.prohibitAllSharing.put(true);
    }

    // Forward exclusion: the gatekeeper may name observers who must not see this observation. Since
    // v1 has no per-thread hiding, the only way to let such an observation proceed is if the named
    // observer has already lost access in the sharing graph. If any named observer is still
    // authorized, we cannot prevent them from seeing it, so we block the observation. See
    // observers-implementation-plan.md §5 Step 5.
    if (description.excludeObservers && description.excludeObservers.length > 0) {
      await this.#enforceExcludeObservers(description.excludeObservers);
    }

    let actionId = this.storage.nextActionId.get();
    this.storage.nextActionId.put(actionId + 1);

    let gatekeeper = this.storage.gatekeepers.get(gatekeeperId);

    let record: ActionRecord = {
      id: actionId,
      gatekeeperId,
      caller,
      resourceTitle: gatekeeper?.resourceTitle,
      resourceUrl: gatekeeper?.resourceUrl,
      createdAt: new Date(),
      state: "approved",
      type: "observation",
      description
    };

    this.storage.actions.put(record);
    this.#associateAction(caller, actionId);
  }
// LAZY REVOCATION MODEL: Access is determined by reachability from the owner in the permission
// graph, recomputed live at every open() (see `getEffectiveRole`). Revocation is therefore lazy:
// removing a collaborator only severs the edges granting *them* access, and revoking a share link
// only flags the link revoked. Nothing cascades, no records are deleted, and downstream edges are
// never touched -- users who lose their only path to the owner simply become unreachable and are
// denied at open() time. Because the graph is never destructively pruned, revocation is reversible:
// re-adding a removed collaborator restores them and, transitively, everyone they had shared with.
// (Records and revoked keys accumulate in storage; a future GC could reclaim long-dead entries.)

#isAdmin(): boolean {
  let name = this.#userId.name;
  let admins = this.env.ADMINS;

  if (!name || !admins) return false;

  if (typeof admins === "string") {
    // Admins should be a JSON binding of array type, but `.env` doesn't actually let you
    // specify JSON bindings, so we also support a string that parses as JSON array.
    admins = JSON.parse(admins);
  }

  if (!Array.isArray(admins)) {
    throw new TypeError("ADMINS must be configured as an array of usernames.");
  }

  return admins.includes(name);
}
async getAdminApi(): Promise<RpcStub<AdminApi> | null> {
  if (!this.#isAdmin()) return null;
  // #isAdmin() guarantees a non-empty user id name. Forwarded to gatekeepers when listing the
  // resource catalog so RBAC-gated ones still surface for this admin.
  let adminUserId = this.#userId.name!;
  // @ts-expect-error Cap'n Web RPC stubs and native RPC targets are compatible but the type
  //     system doesn't know this.
  return new AdminApiImpl(this.adminSettings.getByName(""), adminUserId);
}
async getGatekeeperClassFor(accountId: number, url: string)
    : Promise<{class: DurableObjectClass<Gatekeeper<any>>, vendorId: string,
                typeUrlPattern: string}> {
  let account = this.storage.connectedAccounts.get(accountId);
  if (!account) throw new Error("No such account.");
  let {class: cls, resource} = await account.account.getGatekeeperClassFor(url);

  // Block whole gatekeepers + disabled resources at this single core-side chokepoint where a
  // resourceUrl becomes a capability (reached only via the user/UI-facing Overseer.newGatekeeper
  // and blueprint instantiation — never from gadget or agent code).
  let config = await readAdminConfig(this.env);
  let vendorId = account.vendorId.toLowerCase();
  if (config.disabledGatekeepers.includes(vendorId)) {
    throw new Error(
        `The "${account.vendorId}" gatekeeper is disabled on this deployment by an administrator.`);
  }

  // Blocking here prevents minting a new capability to a disabled resource even if the request
  // bypasses the (separately filtered) picker/agent listings.
  if (isResourceDisabled(config, vendorId, resource.urlPattern)) {
    throw new Error(
        `The "${resource.title}" resource is disabled on this deployment by an administrator.`);
  }

  return {class: cls, vendorId: account.vendorId, typeUrlPattern: resource.urlPattern};
}

// Deployment-wide admin configuration: a single object owned by the AdminSettings durable object and
// mirrored to one reserved BLUEPRINTS KV key, so the per-(re)connect getServerConfig() path and the
// agent can resolve it with a single cheap KV get.
//
// This covers the "soft" deployment customizations only (branding, agent instructions, and which
// gatekeeper connectors/resources are offered). Authentication/authorization config (sign-in
