/**
 * The port a `VITE_BACKEND_HOST` names, as a string, or null when it names no port. Throws on a
 * value that is not a bare `host[:port]`.
 */
export function getWranglerPortFromBackendHost(backendHost: string): string | null {
  const trimmed = backendHost.trim();
  if (!trimmed) return null;
  if (trimmed.includes("://")) {
    throw new Error("VITE_BACKEND_HOST must include a valid host with an optional port.");
  }

  let url: URL;
  try {
    url = new URL(`http://${trimmed}`);
  } catch {
    if (/(^.*\]:|^[^:]+:)[^:]+$/.test(trimmed)) {
      throw new Error("VITE_BACKEND_HOST must include a valid port between 1 and 65535.");
    }
    throw new Error("VITE_BACKEND_HOST must include a valid host with an optional port.");
  }

  if (!url.port) return null;

  const port = Number(url.port);
  if (port < 1) {
    throw new Error("VITE_BACKEND_HOST must include a valid port between 1 and 65535.");
  }

  return url.port;
}

/**
 * Resolve where the dev server's backend lives: an explicit `--port` wins, else
 * `VITE_BACKEND_HOST`, else `localhost:8787`.
 */
export function getDevServerConfig(args: readonly string[], envBackendHost?: string): {
  backendHost: string;
  wranglerPort: string | null;
} {
  let commandLinePort: string | null = null;

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg !== "--port" && !arg.startsWith("--port=")) continue;

    if (commandLinePort !== null) {
      throw new Error("--port may only be specified once.");
    }

    const value = arg === "--port" ? args[++i] : arg.slice("--port=".length);
    if (!/^\d+$/.test(value ?? "") || Number(value) < 1 || Number(value) > 65535) {
      throw new Error("--port must be an integer between 1 and 65535.");
    }
    commandLinePort = String(Number(value));
  }

  if (commandLinePort !== null) {
    return {
      backendHost: `localhost:${commandLinePort}`,
      wranglerPort: commandLinePort,
    };
  }

  const backendHost = envBackendHost?.trim() || "localhost:8787";
  return {
    backendHost,
    wranglerPort: getWranglerPortFromBackendHost(backendHost),
  };
}

// Run a command under two watchdogs -- an idle timer on its output and a total wall-clock cap --
// and kill its whole process tree when either fires.
//
//     node ../../scripts/with-timeout.ts --idle <secs> --max <secs> -- <command> [args...]
//
// It exists because nothing else in the test stack bounds a wedged run. Vite+ has no task timeout
// (`vp run --help` offers only concurrency flags, and `timeout` appears nowhere in its docs), and
// vitest's `testTimeout`/`hookTimeout` are enforced *inside* the test worker, so they die with it;
// the one process-level watchdog, `teardownTimeout`, is armed after the run resolves and therefore
// never arms when the run is what hangs. Underneath that,
// `@cloudflare/vitest-pool-workers` imports Miniflare without passing `onWorkerdCrashRestart`, so a
// workerd that dies mid-run leaves the pool awaiting a reply that will never arrive. The result is
// an unbounded local hang, and in CI an anonymous job-level kill that names no culprit.
//
// Silence is the primary detector rather than wall-clock: a healthy `vitest run` prints a line per
// completed test file, and a wedged one goes quiet. The total cap is the backstop for a command
// that stays chatty while looping forever.
//
// Exit codes: 124 when a threshold fired (GNU `timeout`'s, and distinct from any vitest code), the
// child's own code otherwise, or `128 + signal` when the child or this wrapper was signalled.

import { execFile, spawn } from "node:child_process";
import { constants } from "node:os";
import { resolveBinEntry } from "./bin-entry.ts";
import { collectTree, killProcessTreeEscalating } from "./kill-process-tree.ts";

/** Exit status for a threshold firing, matching GNU `timeout`. */
const TIMED_OUT_EXIT_CODE = 124;

/** How long a signalled tree gets to exit on its own before the SIGKILL. */

// `global_fetch_strictly_public` makes the global fetch() function strictly fetch from
// the public internet in production, rather than the legacy behavior in which same-zone
// requests go directly to origin bypassing Cloudflare. This flag is important to protect
// against SSRF, particularly in the webFetch agent tool, but also generally.
//
// When self-hosting with `workerd` stand-alone, it is already the default behavior that the
// global fetch() function blocks private-network IP addresses or hostnames that resolve to such
// addresses.
//
// Note that `wrangler dev` intentionally reconfigures its global outbound to permit fetching
// from any address (so local services on localhost stay reachable), so this flag effectively
// only takes effect in production or when running workerd stand-alone. That's an acceptable
// tradeoff for dev.
"compatibility_flags": [
  "allow_irrevocable_stub_storage",
  "enhanced_error_serialization",
  "global_fetch_strictly_public",

  // The pi-ai inference layer wraps the official provider SDKs (@anthropic-ai/sdk, openai,
  // @google/genai), which need Node compatibility. Puppeteer (used for Gadget PDF exports)
  // also requires Node compatibility. Otherwise, we'd only need nodejs_als.
  "nodejs_compat"

// Sign-in via authentication gatekeepers.
//
// Unlike the normal connect-account flow (which runs for an already-logged-in user), login happens
// before we know who the user is. The PublicApi starts a gatekeeper connect flow (in "auth" scope
// mode) with a `LoginConnectCallbackImpl` as the callback and a `PendingLogin` DO to bridge the
// result back to the waiting browser:
//
//   1. PublicApi.startGatekeeperLogin(vendorId) creates a PendingLogin DO (keyed by a random DO id),
//      hands the gatekeeper a LoginConnectCallbackImpl, and returns {url, attempt}, where `attempt`
//      is an RpcStub wrapping the DO (so the client awaits via a capability, never a guessable id).
//   2. The browser opens `url` (the gatekeeper's self-closing OAuth popup) and calls
//      `attempt.wait()`, which blocks on the PendingLogin DO.
//   3. When the gatekeeper finishes, it calls LoginConnectCallbackImpl.complete(user). We read the
//      verified email, resolve/create the email-keyed user DO, mint a session, and deliver the token
//      to the PendingLogin DO, which resolves the awaiting RPC.
//
// Sign-in only requests minimal scopes and the gatekeeper grant is transient (it self-destructs
// shortly after we read the email) — so login does NOT create a persistent connected account.
// Capability access (repos, docs, billing) is granted later when the user explicitly connects the
// gatekeeper, which requests the full scopes and persists the connection.
  async startGatekeeperLogin(vendorId: string): Promise<{ url: string; attempt: RpcStub<LoginAttempt> }> {
    if (!getAuthGatekeeperAllowlist(this.env).includes(vendorId)) {
      throw new Error(`Sign-in via "${vendorId}" is not enabled on this deployment.`);
    }
    const vendor = getAuthVendorBinding(this.env, vendorId);
    if (!vendor) throw new Error(`No such auth gatekeeper: ${vendorId}`);
    const desc = await vendor.describe();
    if (!desc.providesAuth) throw new Error(`"${vendorId}" does not provide authentication.`);

    // The PendingLogin DO is the rendezvous between this request and the (separate) OAuth-callback
    // invocation. The client never sees its id — we hand back an `attempt` stub instead.
    const pendingId = this.ctx.exports.PendingLogin.newUniqueId();
    const pending = this.ctx.exports.PendingLogin.get(pendingId);
    const callback = this.ctx.exports.LoginConnectCallbackImpl(
        { props: { pendingId: pendingId.toString(), vendorId } });
    // For most providers, sign-in needs only minimal scopes to verify the user's email (the grant is
    // transient); capability scopes are requested later via an explicit connectAccount. Cloudflare is
    // the exception: signing in with Cloudflare also links AI Gateway billing, so it requests and
    // persists the billing-only scope set up front.
    const options = vendorId === CLOUDFLARE_VENDOR_ID
      ? { scopes: "full" as const, resourceUrlPatterns: [] }
      : { scopes: "auth" as const };
    const { url } = await vendor.connectAccount(callback, options);
    // @ts-expect-error Cap'n Web RPC stubs and native RPC targets are compatible but the type
    //     system doesn't know this.
    return { url, attempt: new LoginAttemptImpl(pending) };
  }

async authenticate(token: string): Promise<void> {
  let tokenBytes: Uint8Array;
  try {
    tokenBytes = Uint8Array.fromBase64(token);
  } catch {
    // A corrupt (non-Base64) token must classify as an auth failure like any other bad token,
    // not surface as the decoder's SyntaxError.
    throw createAuthError(AUTH_ERROR_CODES.invalidSessionToken);
  }
  let hash = await crypto.subtle.digest('SHA-256', tokenBytes);
  let tokenId = new Uint8Array(hash).toHex();
  let session = this.storage.sessions.get(tokenId);
  if (!session) {
    throw createAuthError(AUTH_ERROR_CODES.invalidSessionToken);
  }
}
async #newSessionToken(): Promise<string> {
  let sessionToken = new Uint8Array(32);
  crypto.getRandomValues(sessionToken);

  let tokenId = new Uint8Array(await crypto.subtle.digest('SHA-256', sessionToken)).toHex();
  this.storage.sessions.put({ tokenId, created: new Date() });

  return sessionToken.toBase64();
}

// The caller's effective role. The owner always has "build".
let role: CollaboratorRole = "build";

if (!isOwner) {
  if (this.impl.storage.prohibitAllSharing.get()) {
    // `prohibitAllSharing` can only have been set when the gadget had no shares (see
    // `authorizeObservation`), and no new shares can be created while it's set, so any
    // non-owner reaching here is necessarily unauthorized.
    throw createOpenGadgetError(OPEN_GADGET_ERROR_CODES.workspaceAccessDenied);
  }

  let sharing = await this.impl.getSharingManager();

  // If a share key was provided, redeem it. The owner already has full access and should not
  // appear in the collaborators table.
  if (shareKey) {
    await sharing.redeemShareKey({
      rawKey: shareKey,
      profileId,
      fetchProfile: () => clientUser.whoami(),
    });
  }

  // Check authorization. Compute the caller's effective role from the permission graph; this
  // both authorizes the session and determines which capability we hand back.
  //
  // An unauthorized caller (no effective role -- never had access, or was removed) gets a
  // distinct denial without workspace metadata. A removed collaborator who reconnects after
  // their session is force-restarted lands here and sees the terminal access-denied page.
  let effectiveRole = sharing.getEffectiveRole(profileId);
  if (!effectiveRole) {
    throw createOpenGadgetError(OPEN_GADGET_ERROR_CODES.workspaceAccessDenied);
  }
  role = effectiveRole;

  // Ambient reconciliation may attach Gatekeepers after open() starts. Finish it before taking
  // the observer snapshot so every capability exposed to this collaborator has an observer.
  await ensureCapsules;

  // Verify the caller may observe everything this Gadget has read through its in-scope
  // gatekeepers, configuring their connected accounts if needed. This runs only after a valid
  // role is confirmed, so it never reveals gatekeeper or resource metadata to an unauthorized
  // user. The prohibitAllSharing short-circuit above still wins -- lockdown takes precedence.
  await this.impl.ensureObserver(profileId, clientUser, role, configureObservers);

//
// Note that this collection -- not the set of Y.Doc roots -- is the enumeration source of
// truth for which gadgets exist: content can linger in (or even be resurrected into) the
// files root of a deleted gadget, since Yjs roots can't be deleted and whole-doc sync can't
// stop an old client or later-merged branch from writing there. Such content is inert --
// never listed, loaded, executed, or rendered -- because it has no registry entry.
gadgets: collection<GadgetRecord>()({
  primaryKey: "id",

  uniqueIndexes: {
    // Enforces workspace-wide uniqueness of gadget binding names (see
    // GadgetRecord.bindingName): a put() that would reuse another gadget's name throws.
    // Because pending gadgets' records are real, this makes a provisional gadget reserve its
    // name from the moment of creation, exactly like pending binding edges reserve theirs.
    byBindingName(gadget: GadgetRecord) {
      return gadget.bindingName;
    }
  }
}),

// Bring a non-owner `profileId` into compliance as an observer for their `role`, so that they may
// open the Gadget. May invoke `configureCb` to ask the user to choose connected accounts for
// gatekeeper bindings they haven't configured yet. Re-runs `addObserver` (re-verification) for
// already-configured bindings on every open, catching revocation of the user's underlying
// resource access promptly. Returns when fully verified; throws to deny access.
//
// See observers-implementation-plan.md §5 Step 3.
async ensureObserver(
    profileId: string,
    clientUser: DurableObjectStub<UserDurableObject>,
    role: CollaboratorRole,
    configureCb?: RpcStub<ObserverConfigCallback>): Promise<void> {
  // 1. Select in-scope gatekeepers. If none require an account, there is nothing to verify and
  //    no observer record is needed (built-in gatekeepers never name observers in
  //    excludeObservers).
  let inScope = this.#inScopeGatekeepers(role);
  if (inScope.length === 0) return;

  // 2. Load any existing observer record, and build a working copy of its account choices.
  let record = this.storage.observers.get(profileId);
  let accountChoices: {[gatekeeperId: number]: number} = {...record?.accountChoices};

  // Gatekeeper ids registered before this call (their account choice came from the persisted
  // record). An immutable snapshot: on a verification failure we roll back only observers we
  // registered *this* call, leaving pre-existing registrations intact.
  let registeredBeforeCall = new Set<number>(
      inScope.filter(gk => gk.id in accountChoices).map(gk => gk.id));

  let observerId = record?.observerId ?? crypto.randomUUID();
  // Gatekeepers we successfully registered the observer with during this call.
  let newlyAdded = new Set<number>();

  // Failures from the previous pass, keyed by gatekeeper id: an already-configured binding whose
  // chosen account was disconnected, or which the gatekeeper refused.
  let passFailures = new Map<number, ObserverBindingFailure>();

  // We may need to re-prompt the configuration modal when an already-configured binding fails, so
  // the user can fix it in place. Bound the number of such re-prompts to avoid looping against a
  // misbehaving client (or an account that simply keeps failing).
  let reprompts = 0;
  const MAX_CONFIG_REPROMPTS = 1;

  try {
    while (true) {
      // 3. Determine uncovered bindings: in-scope gatekeepers with no account choice yet. Ambient
      //    bindings use the collaborator's matching provided account automatically; unlike an
      //    ordinary connection, there is no meaningful account choice when one already exists.
      //    On a re-prompt, leave a failed ambient binding uncovered so the client can explain the
      //    failure rather than silently retrying the same account.
      let uncovered = inScope.filter(gk => !(gk.id in accountChoices));
      let ambientNeeds = uncovered.flatMap(gk => {
        let spec = gk.creationSpec;
        return spec?.type === "ambient" && !passFailures.has(gk.id)
            ? [{gatekeeperId: gk.id, vendorId: spec.vendorId}]
            : [];
      });
      if (ambientNeeds.length > 0) {
        let accountsByVendor = new Map<string, number>();
        for (let account of await clientUser.listProvidedAccounts()) {
          if (account.description.singleton && !accountsByVendor.has(account.vendorId)) {
            accountsByVendor.set(account.vendorId, account.accountId);
          }
        }
        for (let need of ambientNeeds) {
          let accountId = accountsByVendor.get(need.vendorId);
          if (accountId !== undefined) accountChoices[need.gatekeeperId] = accountId;
        }
        uncovered = inScope.filter(gk => !(gk.id in accountChoices));
      }

      // 4. If there are uncovered bindings, ask the client to choose accounts for them.
      if (uncovered.length > 0) {
        if (!configureCb) {
          // Non-interactive open (e.g. no UI). We can't configure, so deny.
          throw new Error(
              "To open this workspace, you must choose connected accounts for the services it " +
              "uses, but no configuration channel was provided.");
        }

  nextHookId: 0,

  // True if any past observation was authorized that had the `prohibitAllSharing` flag set
  // in its `ObservationDescription`.
if (!isOwner) {
  if (this.impl.storage.prohibitAllSharing.get()) {
    // `prohibitAllSharing` can only have been set when the gadget had no shares (see
    // `authorizeObservation`), and no new shares can be created while it's set, so any
    // non-owner reaching here is necessarily unauthorized.
    throw createOpenGadgetError(OPEN_GADGET_ERROR_CODES.workspaceAccessDenied);

